import sys
from collections import defaultdict

def main():
    sys.setrecursionlimit(100000)
    input = sys.stdin.readline

    n, m = map(int, input().split())

    adj = defaultdict(list)

    for _ in range(m):
        u, v = map(int, input().split())
        adj[u].append(v)
        adj[v].append(u)

    if n == 0 or m == 0:
        return

    disc = [0] * n
    low = [0] * n
    visited = [False] * n
    time = [0]
    bridges = []

    def dfs(u, parent):
        visited[u] = True
        disc[u] = low[u] = time[0]
        time[0] += 1

        for v in adj[u]:
            if not visited[v]:
                dfs(v, u)
                low[u] = min(low[u], low[v])

                if low[v] > disc[u]:
                    bridges.append((min(u, v), max(u, v)))
            elif v != parent:
                low[u] = min(low[u], disc[v])

    for i in range(n):
        if not visited[i]:
            dfs(i, -1)

    bridge_set = set(bridges)

    for u, v in bridges:
        print(u, v)

if __name__ == "__main__":
    main()
